    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Loop through the items and update the maximum happiness for each item
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # If the price of the current item is less than or equal to the budget,
            # update the maximum happiness
            if items[i - 1][0] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - items[i - 1][0]] + items[i - 1][1])
            else:
                dp[i][j] = dp[i - 1][j]

    # Return the maximum happiness for the last item
    return dp[m][n]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    result = ""
    for i in range(n+1):
        if coeffs[i] != 0:
            sign = "+" if coeffs[i] > 0 else ""
            abs_coeff = abs(coeffs[i])
            if abs_coeff == 1 and i > 0:
                abs_coeff = ""
            else:
                abs_coeff = str(abs_coeff)
            if i == 0:
                result += abs_coeff
            elif i == 1:
                result += f"{sign}{abs_coeff}x"
            else:
                result += f"{sign}{abs_coeff}x^{i}"
    return result.strip()

